import{_ as r,o,c as e,a2 as a}from"./chunks/framework.A5mep7Fe.js";const g=JSON.parse('{"title":"💵 05 · 薪资谈判与 Offer 选择","description":"","frontmatter":{},"headers":[],"relativePath":"09-面试实战/05-薪资谈判与Offer选择.md","filePath":"09-面试实战/05-薪资谈判与Offer选择.md","lastUpdated":1786806808000}'),l={name:"09-面试实战/05-薪资谈判与Offer选择.md"};function i(n,t,s,d,f,h){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="💵-05-·-薪资谈判与-offer-选择" tabindex="-1">💵 05 · 薪资谈判与 Offer 选择 <a class="header-anchor" href="#💵-05-·-薪资谈判与-offer-选择" aria-label="Permalink to &quot;💵 05 · 薪资谈判与 Offer 选择&quot;">​</a></h1><blockquote><p>技术帮你拿到 offer，谈薪帮你「兑现价值」。本篇讲策略与避坑（数据为社区整理，存在个体差异，仅供参考）。</p></blockquote><hr><h2 id="一、薪资结构-先搞懂再谈" tabindex="-1">一、薪资结构（先搞懂再谈） <a class="header-anchor" href="#一、薪资结构-先搞懂再谈" aria-label="Permalink to &quot;一、薪资结构（先搞懂再谈）&quot;">​</a></h2><ul><li><strong>Base（月薪）</strong>：谈薪主战场</li><li><strong>绩效/奖金</strong>：通常 2-6 个月，看评级</li><li><strong>股票/期权（RSU/Option）</strong>：分 4 年归属，大厂/独角兽占比高</li><li><strong>签字费（Sign-on）</strong>：一次性，可谈</li><li><strong>补贴</strong>：餐补/房补/加班费（注意是否含在 base 里）</li></ul><blockquote><p>总包 = Base×12 + 奖金 + 股票年均 + 签字费。比较 offer 看<strong>年总包</strong>而非月薪。</p></blockquote><h2 id="二、谈薪策略" tabindex="-1">二、谈薪策略 <a class="header-anchor" href="#二、谈薪策略" aria-label="Permalink to &quot;二、谈薪策略&quot;">​</a></h2><ol><li><strong>先让对方出价</strong>：别先报底价。「您这边预算范围是多少？」</li><li><strong>给区间而非死数</strong>：基于市场 + 自身水平给合理区间</li><li><strong>用其他 offer 杠杆</strong>：礼貌告知有竞争 offer（真实），促匹配</li><li><strong>争取签字费/股票</strong>：base 卡死时可谈 sign-on 或 RSU</li><li><strong>书面确认</strong>：口头不算，要书面 offer 明细</li></ol><h2 id="三、offer-对比维度-不只看钱" tabindex="-1">三、Offer 对比维度（不只看钱） <a class="header-anchor" href="#三、offer-对比维度-不只看钱" aria-label="Permalink to &quot;三、Offer 对比维度（不只看钱）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>为什么重要</th></tr></thead><tbody><tr><td>总包与成长性</td><td>当下收入 + 未来涨幅</td></tr><tr><td>业务前景</td><td>部门是否会裁/战略优先级</td></tr><tr><td>技术成长</td><td>能否学到跨周期能力</td></tr><tr><td>团队与上级</td><td>直接决定幸福感与成长</td></tr><tr><td>工作强度</td><td>长期可持续性</td></tr><tr><td>城市/生活</td><td>成本、家庭</td></tr></tbody></table><blockquote><p>原则：<strong>第一份/早期更看重「成长与平台」，中期更看重「总包与稳定」</strong>。别只看月薪。</p></blockquote><h2 id="四、避坑" tabindex="-1">四、避坑 <a class="header-anchor" href="#四、避坑" aria-label="Permalink to &quot;四、避坑&quot;">​</a></h2><ul><li>别在 HR 面过早暴露底线薪资</li><li>警惕「画饼」：口头承诺的股票/晋升不算数，看书面</li><li>注意期权 vs RSU（期权可能归零，RSU 更稳）</li><li>别因一个 offer 就停止面试，多拿几个才有议价权</li><li>离职原因别抱怨前公司，讲「发展/方向」客观原因</li></ul><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q：期望薪资怎么说？</strong></p><blockquote><p>先问对方预算；若必须说，给「基于市场与能力的合理区间」，并强调看整体 package 与发展。避免报死数卡死自己。</p></blockquote><p><strong>Q：两个 offer 一个钱多一个成长好怎么选？</strong></p><blockquote><p>看阶段：早期选成长平台（能力复利）；若已有积累且需变现，选总包。再综合业务前景、团队、城市。没有标准答案，列维度打分。</p></blockquote><hr><p>➡️ 返回：<a href="./README">09-面试实战 README</a> ｜ 进入：<a href="./../10-职业发展与资源/README">10-职业发展与资源</a></p>',20)])])}const u=r(l,[["render",i]]);export{g as __pageData,u as default};
